import{_ as s,o as t,c as a,a3 as i}from"./chunks/framework.Ch_0qWu9.js";const u=JSON.parse('{"title":"Offline Solver adapters","description":"","frontmatter":{"sourcePath":"docs/offline-adapters.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/offline-adapters.md","alternateUrl":"/TCSExam/docs/zh/offline-adapters/","alternateAnchors":{"offline-solver-adapters":"offline-solver-adapters","run-a-suite":"run-a-suite","execution-host-resources":"execution-host-resources","judging-and-results":"judging-and-results","troubleshooting":"troubleshooting","build-a-selected-adapter":"build-a-selected-adapter"}},"headers":[],"relativePath":"offline-adapters/index.md","filePath":"offline-adapters/index.md"}'),r={name:"offline-adapters/index.md"};function o(n,e,l,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="offline-solver-adapters" tabindex="-1">Offline Solver adapters <a class="header-anchor" href="#offline-solver-adapters" aria-label="Permalink to &quot;Offline Solver adapters&quot;">​</a></h1><p>This guide describes local Docker execution for Offline Solver judging. It is for users preparing public self-tests and hidden final judging.</p><h2 id="run-a-suite" tabindex="-1">Run a suite <a class="header-anchor" href="#run-a-suite" aria-label="Permalink to &quot;Run a suite&quot;">​</a></h2><p>After <a href="/TCSExam/docs/getting-started/">installing the runtime and configuring a model</a>, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>Use <code>--suite full</code> for all thirty Solver tasks or <code>--task TASK_ID</code> for one task. The builder prepares development and verifier images and saves their identities in the local cache. <code>doctor</code> checks the selected images and execution host. Resolve its reported blockers before starting the run.</p><p>During final judging, Harbor starts a verifier controller. The controller creates isolated Docker workers, supplies the submission and assigned hidden inputs, collects their results and removes its workers. Offline execution uses this per-attempt controller; Online service deployment is described in the <a href="/TCSExam/docs/backend/docker/">Docker backend guide</a>.</p><h2 id="execution-host-resources" tabindex="-1">Execution-host resources <a class="header-anchor" href="#execution-host-resources" aria-label="Permalink to &quot;Execution-host resources&quot;">​</a></h2><p>Use a rootful Linux Docker daemon with <code>/var/run/docker.sock</code> on the execution host. The verifier&#39;s <code>tests/docker-compose.yaml</code> mounts this socket and a read-only host cgroup tree and uses the host PID and cgroup namespaces. The CLI user needs Docker access. This compose configuration requires the standard socket path, including when selecting a Docker context.</p><p>The socket belongs exclusively to the trusted verifier controller. Development containers and judging workers run without it. Judge workers also require <a href="/TCSExam/docs/judge-execution-isolation/">Landlock and the image preflight</a>; build and solver commands run as UID/GID 65534 under root supervision.</p><p>Worker reservations are declared in each task&#39;s <code>tests/runtime/task.json</code>. The controller admits workers only when their full CPU and memory reservations fit, with one additional CPU and 512 MiB reserved for the controller. For example, a 32 GiB worker requires at least 33,280 MiB of visible host memory, plus enough free memory and disk at admission time. A four-CPU worker needs at least five visible CPUs including the controller reserve. The development container has its own additional requirements, checked before model execution.</p><p>Each task uses at most ten concurrent judging workers. Smaller hosts run fewer workers at once while preserving each worker&#39;s resources and each instance&#39;s solver budget. Where a task declares shared shard memory, a worker reserves the full amount. Insufficient capacity produces an environment error with the required resources in the report.</p><h2 id="judging-and-results" tabindex="-1">Judging and results <a class="header-anchor" href="#judging-and-results" aria-label="Permalink to &quot;Judging and results&quot;">​</a></h2><p>Each worker invokes the task&#39;s preparation script and checker for its assigned instances. The checker validates the candidate output and computes its objective value. The controller combines the complete instance records into the final task result. See <a href="/TCSExam/docs/scoring/">scoring</a> for task rewards, failed judging and Index calculation.</p><p>Bin packing, graph partitioning, sports timetabling, logic synthesis, quadratic assignment and set covering each use one worker for the complete shared time pool: all instances share one total solver budget. Keep these groups intact when configuring parallelism. Other tasks use their declared per-instance limits and grouping.</p><p>The outer worker deadline allows time for compilation, solving and validation. The scoring program separately enforces the task&#39;s solver budget. CPU indices used by a scorer map to the CPUs reserved for its worker.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Action</th></tr></thead><tbody><tr><td>Docker socket or cgroup access fails</td><td>Run on the rootful Docker host with the standard socket and the task&#39;s verifier compose configuration.</td></tr><tr><td>Judge startup reports an isolation error</td><td>Run the image preflight on that host and resolve the reported kernel, syscall or identity-transition requirement.</td></tr><tr><td>Worker admission reports insufficient capacity</td><td>Free the required resources or choose a larger host; retain the task&#39;s declared worker size.</td></tr><tr><td>Initial archive upload fails</td><td>Inspect <code>resources.json</code>. The controller automatically retries the specific pre-start missing-root error up to three times with the same submission and instance group. Other errors are reported for operator action.</td></tr><tr><td>A result is missing or judging failed</td><td>Inspect the verifier logs and instance records before calculating the task score.</td></tr></tbody></table><h2 id="build-a-selected-adapter" tabindex="-1">Build a selected adapter <a class="header-anchor" href="#build-a-selected-adapter" aria-label="Permalink to &quot;Build a selected adapter&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ce-pace2021</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span></code></pre></div><p>The task&#39;s <code>offline-adapter.json</code> declares its Online development image, backend and verifier-tool dependencies. The builder resolves these dependencies and reuses unchanged local products. For resource inputs and cache options, see <a href="/TCSExam/docs/resources/">resource preparation</a>. For development and source checks, see <a href="/TCSExam/docs/contributing/">contributing</a>.</p>`,21)])])}const k=s(r,[["render",o]]);export{u as __pageData,k as default};
